description:
Do the compiler's job: given a struct's members in declaration order, each with a size and an alignment, work out where each one goes.

```cpp
struct Member { std::string name; int size; int align; };

std::vector<int> offsetsOf(const std::vector<Member>& members);
int sizeOf(const std::vector<Member>& members);
int paddingOf(const std::vector<Member>& members);
std::vector<Member> smallestOrder(const std::vector<Member>& members);
```

- **offsetsOf**: each member goes at the next offset that is a multiple of its alignment.
- **sizeOf**: the end of the last member, rounded up to a multiple of the largest alignment. An empty struct has size 1 (C++ gives every object at least one byte).
- **paddingOf**: the size minus the sum of the members' sizes.
- **smallestOrder** returns the members sorted by alignment, largest first; members with the same alignment keep their original order. That order never needs more padding than any other.

The tests compare your answers with what the real compiler does, using `offsetof` and `sizeof`.

starter.solution.cpp:
#include <string>
#include <vector>

struct Member { std::string name; int size; int align; };

std::vector<int> offsetsOf(const std::vector<Member>& members) { return {}; }
int sizeOf(const std::vector<Member>& members) { return 0; }
int paddingOf(const std::vector<Member>& members) { return 0; }
std::vector<Member> smallestOrder(const std::vector<Member>& members) { return members; }

solution.solution.cpp:
#include <algorithm>
#include <string>
#include <vector>

struct Member { std::string name; int size; int align; };

static int roundUp(int value, int align) { return (value + align - 1) / align * align; }

std::vector<int> offsetsOf(const std::vector<Member>& members)
{
    std::vector<int> offsets;
    int at{ 0 };
    for (const Member& m : members)
    {
        at = roundUp(at, m.align);
        offsets.push_back(at);
        at += m.size;
    }
    return offsets;
}

int sizeOf(const std::vector<Member>& members)
{
    if (members.empty()) return 1;
    const std::vector<int> offsets{ offsetsOf(members) };
    int largest{ 1 };
    for (const Member& m : members) largest = std::max(largest, m.align);
    return roundUp(offsets.back() + members.back().size, largest);
}

int paddingOf(const std::vector<Member>& members)
{
    int used{ 0 };
    for (const Member& m : members) used += m.size;
    return members.empty() ? 0 : sizeOf(members) - used;
}

std::vector<Member> smallestOrder(const std::vector<Member>& members)
{
    std::vector<Member> sorted{ members };
    std::stable_sort(sorted.begin(), sorted.end(), [](const Member& a, const Member& b) { return a.align > b.align; });
    return sorted;
}

unitTests:
#include <cstddef>
#include <cstdint>
struct Pickup { char kind; double expires; int amount; bool active; };
struct Mixed { short s; char c; int i; char d; long long ll; };
struct Vec3 { float x, y, z; };
struct Bones { char tag; Vec3 position; std::uint16_t id; };
using Ms = std::vector<Member>;
static const Ms pickup{ { "kind", 1, 1 }, { "expires", 8, 8 }, { "amount", 4, 4 }, { "active", 1, 1 } };
static const Ms mixed{ { "s", 2, 2 }, { "c", 1, 1 }, { "i", 4, 4 }, { "d", 1, 1 }, { "ll", 8, 8 } };
static const Ms bones{ { "tag", 1, 1 }, { "position", 12, 4 }, { "id", 2, 2 } };

TEST("offsets match the compiler") {
    CHECK_EQ(offsetsOf(pickup), (std::vector<int>{ (int)offsetof(Pickup, kind), (int)offsetof(Pickup, expires), (int)offsetof(Pickup, amount), (int)offsetof(Pickup, active) }));
    CHECK_EQ(offsetsOf(mixed), (std::vector<int>{ (int)offsetof(Mixed, s), (int)offsetof(Mixed, c), (int)offsetof(Mixed, i), (int)offsetof(Mixed, d), (int)offsetof(Mixed, ll) }));
    CHECK_EQ(offsetsOf(bones), (std::vector<int>{ (int)offsetof(Bones, tag), (int)offsetof(Bones, position), (int)offsetof(Bones, id) }));
}
TEST("sizes match the compiler") {
    CHECK_EQ(sizeOf(pickup), (int)sizeof(Pickup));
    CHECK_EQ(sizeOf(mixed), (int)sizeof(Mixed));
    CHECK_EQ(sizeOf(bones), (int)sizeof(Bones));
    CHECK_EQ(sizeOf(Ms{}), 1);
    CHECK_EQ(sizeOf(Ms{ { "c", 1, 1 } }), 1);
}
TEST("padding") {
    CHECK_EQ(paddingOf(pickup), 10);
    CHECK_EQ(paddingOf(bones), 5);
    CHECK_EQ(paddingOf(Ms{ { "a", 8, 8 } }), 0);
}
TEST("a better order") {
    const Ms better{ smallestOrder(pickup) };
    CHECK_EQ(better[0].name, std::string("expires"));
    CHECK_EQ(better[1].name, std::string("amount"));
    CHECK_EQ(better[2].name, std::string("kind"));
    CHECK_EQ(better[3].name, std::string("active"));
    CHECK_EQ(sizeOf(better), 16);
    CHECK_EQ(sizeOf(smallestOrder(mixed)), 16);
    CHECK(sizeOf(smallestOrder(mixed)) < sizeOf(mixed));
}

